(function(root){
'use strict';
const multiply=(a,v)=>[a[0]*v[0]+a[1]*v[1],a[2]*v[0]+a[3]*v[1]];
const graphics={stretch:{matrix:[2,0,0,1],name:'Stretch horizontally',explanation:'Every horizontal component doubles. Vertical components stay the same.'},turn:{matrix:[0,1,-1,0],name:'Turn 90° clockwise',explanation:'A right-pointing direction turns downward. An upward direction turns right.'}};
function neural(){const input=[1,2],weights=[1,1,-1,1],bias=[0,-2],mixed=multiply(weights,input),shifted=mixed.map((n,i)=>n+bias[i]),activated=shifted.map(n=>Math.max(0,n));return{input,weights,bias,mixed,shifted,activated};}
const pair=v=>'('+v.join(', ')+')';
const matrix=a=>`<span class="material-matrix" aria-label="Matrix rows ${a[0]}, ${a[1]}; ${a[2]}, ${a[3]}">${a.map(n=>`<span>${n}</span>`).join('')}</span>`;
function intro(host,{onBegin,onExplore,resuming=false}={}){
 host.innerHTML=`<section class="student-intro"><span class="eyebrow">Start here · Linear algebra</span><h1>Show your starting point. Choose your next step.</h1><p class="intro-lead">Use this check-in alongside your matrix lesson. Your answers make parts of your method visible, so the report can suggest what to revisit and how to check it in another example.</p><div class="intro-purpose"><h2>Why are we starting with a few questions?</h2><p>Show what you can calculate and explain. You can choose “Not studied yet” for a new topic. Your lesson focus is to read matrix columns, calculate a transformed vector, and explain the original coefficients.</p></div><div class="intro-actions"><button id="begin-learning" class="btn primary">${resuming?'Return to my activity':'Begin the 3-question starting check'}</button><button id="explore-materials" class="btn">See where linear algebra is used</button></div><p class="intro-context-note">The application examples include explanations. If you view them before answering, that learning context stays with your responses.</p><section class="intro-connection"><h2>Other activities in this subject</h2><p>This matrix lesson has 3 starting questions, 2 practice questions, 3 fresh questions, one lesson prediction, and 2 optional later-check questions. It is one route, not the whole subject.</p><ul><li><a href="vectors.html">Vector diagnostic</a> · 8 starting tasks, with up to 3 optional follow-ups.</li><li><a href="../../../foundations/?module=ab01">Foundation checks</a> · 15 entry questions and 8 further questions in separate checks.</li><li><a href="../../../diagnostics/?module=ab01">Diagnostic challenges</a> · 12 multi-step problems.</li><li><a href="../../../projects/?module=ab01">Field projects</a> · 2 larger projects.</li><li><a href="matrix.html">Matrix Lab</a> · guided and exploratory teaching.</li></ul><p>You can choose the route you need; these activities are not a required checklist.</p></section><section class="intro-connection"><h2>Where can this foundation lead?</h2><div class="intro-uses"><article><h3>Change a picture</h3><p>Describe how points turn or stretch using the same operation.</p></article><article><h3>Organize equations</h3><p>Collect several equations and unknown quantities into one matrix relationship.</p></article><article><h3>Follow an AI calculation</h3><p>See how one layer combines input numbers using weights. Later lessons connect this to larger models.</p></article></div><p>The subject grows from two-dimensional pictures to many-dimensional data. This activity starts with a small, visible part of that larger subject.</p></section><section class="intro-process"><h2>What happens in this activity?</h2><ol><li><span>Starting check</span>Try three questions before the guided lesson. Feedback comes later.</li><li><span>Step-by-step lesson</span>Watch the changes, pause, and make a prediction.</li><li><span>Supported practice</span>Use hints and feedback when they help.</li><li><span>Fresh tasks</span>Try different questions without immediate task hints.</li><li><span>Your report</span>Choose a suggested priority, see the responses behind it, and try the proposed practice. Optionally return after at least one day.</li></ol></section><details><summary>What will the report tell me?</summary><p>It records your answers, revisions and help used. “Matched after a hint” and “matched on a fresh task” describe different learning conditions. A few answers cannot establish everything you know.</p><p>Everyone uses the same guided example in this version. The report suggests focused next steps using your recorded responses. Use them with your teacher’s lesson goals and classwork or exam criteria. The advanced branches below are a learning map; they are not automatic AI-selected lessons in this version.</p></details></section>`;
 host.querySelector('#begin-learning').onclick=onBegin;
 host.querySelector('#explore-materials').onclick=onExplore;
}
function diagram(a){
 const points=[[0,0],[1,0],[1,1]],after=points.map(p=>multiply(a,p));
 const panel=(ps,title,color)=>{const X=n=>95+n*55,Y=n=>155-n*55;return`<div class="material-plot"><h3>${title}</h3><svg viewBox="0 0 330 250" role="img" aria-label="${title}: triangle vertices ${ps.map(pair).join('; ')}"><path d="M25 155H305M95 235V30" stroke="#a2b3c7" fill="none"/><text x="305" y="177">x</text><text x="105" y="31">y</text><text x="85" y="177">0</text><polygon points="${ps.map(p=>X(p[0])+','+Y(p[1])).join(' ')}" fill="${color}" fill-opacity=".12" stroke="${color}" stroke-width="3"/>${ps.map(p=>`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="4" fill="${color}"/><text x="${X(p[0])+7}" y="${Y(p[1])-10}">${pair(p)}</text>`).join('')}</svg></div>`;};
 return panel(points,'Original coordinates','#087e73')+panel(after,'Transformed coordinates','#3658d4');
}
function applications(host,{onBack,onExposure}={}){
 let topic='graphics',mode='stretch',step=0;
 function draw(){
 host.innerHTML=`<section class="student-materials"><div class="topline"><div><span class="eyebrow">Application guide · optional explanations</span><h1>What can linear algebra help us do?</h1><p class="muted">Try a small example, then see where the same idea leads. Each example is a connection to explore, not another scored task.</p></div><button id="materials-back" class="text-btn">Back to the introduction</button></div><div class="material-tabs" role="group" aria-label="Application examples">${[['graphics','Change a shape'],['systems','Connect equations'],['neural','Inside one AI layer']].map(([id,label])=>`<button class="btn" data-material-topic="${id}" aria-pressed="${topic===id}">${label}</button>`).join('')}</div><section id="material-example" class="card material-example"></section>${roadmap()}<details class="material-sources"><summary>Sources and further reading</summary><p>These small examples were written for Quidence. The links below explain the underlying ideas.</p><ul><li><a href="https://ocw.mit.edu/courses/18-06sc-linear-algebra-fall-2011/" target="_blank" rel="noopener">MIT OpenCourseWare: linear algebra, equations, least squares and decompositions</a></li><li><a href="https://docs.pytorch.org/docs/stable/generated/torch.nn.Linear.html" target="_blank" rel="noopener">PyTorch: weighted linear layer with bias</a></li><li><a href="https://docs.pytorch.org/docs/stable/generated/torch.nn.ReLU.html" target="_blank" rel="noopener">PyTorch: the ReLU activation</a></li><li><a href="https://developers.google.com/machine-learning/crash-course/embeddings/embedding-space" target="_blank" rel="noopener">Google Machine Learning Crash Course: embedding spaces</a></li></ul></details><div class="intro-actions"><button id="materials-return" class="btn dark">Back to the introduction</button><button id="print-materials" class="btn">Print this example and map</button></div></section>`;
 const example=host.querySelector('#material-example');
 if(topic==='graphics'){
  const g=graphics[mode],output=multiply(g.matrix,[1,1]);
  example.innerHTML=`<span class="eyebrow">Geometry and graphics</span><h2>The same matrix acts on every point.</h2><p>A triangle is described by three coordinate pairs. Apply one matrix to each pair to change the triangle.</p><div class="material-controls">${Object.entries(graphics).map(([id,g])=>`<button class="btn" data-graphic-mode="${id}" aria-pressed="${mode===id}">${g.name}</button>`).join('')}</div><div class="material-plots">${diagram(g.matrix)}</div><div class="material-calculation">${matrix(g.matrix)}<span>× (1, 1) = ${pair(output)}</span></div><p class="material-meaning">${g.explanation} A graphics program can repeat this operation for many points.</p><p class="review-text">These examples turn and stretch about the origin. Moving a shape by a fixed offset requires an added translation or an extended coordinate representation.</p>`;
  example.querySelectorAll('[data-graphic-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.graphicMode;onExposure?.({topic,step:mode});draw();});
 }else if(topic==='systems'){
  const descriptions=[['Start with two receipts.','Two notebooks and one pen cost $7. One notebook and two pens cost $5. We want the two unit prices.'],['Name the unknowns.','Let n be the price of one notebook and p the price of one pen. Each receipt gives one equation.'],['Organize the quantities.','The matrix stores the purchase counts. The unknown vector stores the unit prices. The output vector stores the receipt totals.'],['Check one solution.','If a notebook costs $3 and a pen costs $1, both receipt totals match. A solution must satisfy both equations.']];
  example.innerHTML=`<span class="eyebrow">Systems of equations</span><h2>${descriptions[step][0]}</h2><p>${descriptions[step][1]}</p><div class="material-steps" role="group" aria-label="Receipt example steps">${['Read receipts','Name unknowns','Use a matrix','Check prices'].map((s,i)=>`<button class="btn" data-example-step="${i}" aria-pressed="${step===i}">${i+1}. ${s}</button>`).join('')}</div><table class="material-table"><caption>Two purchases, the same unknown unit prices</caption><thead><tr><th>Receipt</th><th>Notebooks</th><th>Pens</th><th>Total</th></tr></thead><tbody><tr><th>First</th><td>2</td><td>1</td><td>$7</td></tr><tr><th>Second</th><td>1</td><td>2</td><td>$5</td></tr></tbody></table>${step>=1?'<div class="material-equations">2n + p = 7<br>n + 2p = 5</div>':''}${step>=2?`<div class="material-calculation">${matrix([2,1,1,2])}<span>× (n, p) = (7, 5)</span></div><p>One matrix relationship contains both equations.</p>`:''}${step===3?'<div class="material-equations">2 × 3 + 1 = 7<br>3 + 2 × 1 = 5</div><p class="material-meaning">Matrix multiplication describes both totals at once. Later, methods for solving systems help recover unknown quantities. With noisy data, least squares looks for a best fit.</p>':''}`;
 }else{
  const n=neural(),titles=['Describe the input with numbers.','Mix the input using weights.','Add a bias.','Apply a non-linear activation.'],explanations=['Use the small input vector x = (1, 2). In real applications, inputs may be numerical features or learned representations.','Each output combines the input numbers with different weights. A matrix organizes those weights.','The bias shifts the intermediate result. This step adds a vector after matrix multiplication.','ReLU keeps positive values and replaces negative values with zero. This extra operation is not a matrix multiplication.'];
  example.innerHTML=`<span class="eyebrow">Neural networks · a small worked example</span><h2>${titles[step]}</h2><p>${explanations[step]}</p><div class="material-steps" role="group" aria-label="Neural layer steps">${['Input numbers','Weight matrix','Add bias','Activation'].map((s,i)=>`<button class="btn" data-example-step="${i}" aria-pressed="${step===i}">${i+1}. ${s}</button>`).join('')}</div><div class="neural-stage"><span class="tag">${['Input x','Weighted sum Wx','Shifted result Wx + b','Activated output'][step]}</span><output aria-live="polite">${pair([n.input,n.mixed,n.shifted,n.activated][step])}</output></div>${step>=1?`<div class="material-calculation">W = ${matrix(n.weights)}<span>Wx = (1 × 1 + 1 × 2, −1 × 1 + 1 × 2) = (3, 1)</span></div>`:''}${step>=2?'<div class="material-equations">b = (0, −2)<br>(3, 1) + (0, −2) = (3, −1)</div>':''}${step===3?'<div class="material-equations">ReLU(3, −1) = (max(0, 3), max(0, −1)) = (3, 0)</div>':''}<p class="review-text">The weights and bias here were chosen to make the arithmetic visible. The output is an intermediate vector. We have not trained a model or assigned meaning to its two output numbers.</p><details><summary>What does “deep” mean here?</summary><p>A deep neural network uses multiple processing layers. Many layers combine matrix operations with other operations, including non-linear activations.</p><p>Stacking only matrix multiplications can be combined into one matrix product. Even with added biases, a sequence of purely affine steps remains affine. Non-linear operations allow more varied functions. Understanding one small weighted sum is a useful first connection; it is not the whole network.</p></details>`;
 }
 example.querySelectorAll('[data-example-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.exampleStep);onExposure?.({topic,step});draw();});
 host.querySelectorAll('[data-material-topic]').forEach(b=>b.onclick=()=>{topic=b.dataset.materialTopic;step=0;onExposure?.({topic,step:topic==='graphics'?mode:step});draw();});
 host.querySelector('#materials-back').onclick=onBack;host.querySelector('#materials-return').onclick=onBack;
 host.querySelector('#print-materials').onclick=()=>root.print?.();
 }
 onExposure?.({topic,step:mode});draw();
}
function roadmap(){return`<section class="material-roadmap"><span class="eyebrow">A learning map, not a required checklist</span><h2>Start small. See the wider branches.</h2><p>The subject is broad, and some later ideas need substantial practice. You can begin with vectors and a visible transformation without learning all the branches at once.</p><div class="material-levels"><article><span class="tag">Current foundation lesson</span><h3>Foundation</h3><p>Coordinates, columns, vector combinations and a 2 × 2 matrix acting on a vector.</p><p>Ask: “What changed, and what stayed the same?”</p></article><article><span class="tag">Examples in this guide</span><h3>Connections</h3><p>Transform a shape, combine equations, and follow one neural layer’s calculation.</p><p>Ask: “Where does the same operation appear?”</p></article><article><span class="tag">Later learning directions</span><h3>Greater depth</h3><p>Higher-dimensional spaces, dot products, projections, least squares, eigenvectors and matrix decompositions.</p><p>Ask: “What structure can this operation reveal?”</p></article></div><table class="material-table"><caption>Possible branches after the foundation</caption><thead><tr><th>Branch</th><th>A question it helps answer</th><th>Ideas to learn later</th></tr></thead><tbody><tr><th>Graphics and geometry</th><td>How do many coordinates change together?</td><td>Composition, inverses and coordinate systems</td></tr><tr><th>Data and modeling</th><td>What relationship best fits measurements?</td><td>Systems, projections and least squares</td></tr><tr><th>AI representations</th><td>How can words or other data be represented and compared numerically?</td><td>Many-dimensional vectors, embeddings, dot products and similarity</td></tr><tr><th>Deep learning</th><td>How are numerical features changed across processing layers?</td><td>Weight matrices, biases, non-linear activations, training and calculus</td></tr></tbody></table><p class="review-text">Embeddings often have many dimensions, and a dimension need not have a simple human-readable meaning. The two coordinates in our drawing are a starting representation, not a literal map of an AI model’s internal space.</p><p class="material-meaning">The interactive examples above are available now. The deeper branches are a map for future learning; AB01 does not yet provide complete lessons or adaptive assessment for them.</p></section>`;}
const api={multiply,graphics,neural,intro,applications};root.AB01Materials=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
